-- Converted: GRANT EXECUTE PROCEDURE ON sales.add_payment TO operator -> GRANT USAGE ON PROCEDURE SALES.ADD_PAYMENT(<argument types>) TO ROLE OPERATOR, issued from an anonymous Snowflake Scripting block that reads the argument types of SALES.ADD_PAYMENT from SHOW USER PROCEDURES.
-- Reason: Snowflake has no EXECUTE PROCEDURE privilege; USAGE on the procedure is what allows a role to CALL it, and a procedure is only addressable together with its argument type list. The batch does not carry the converted ADD_PAYMENT argument list, so it is read from the catalog at deploy time instead of being guessed. Object privileges go to roles in Snowflake, so the Teradata grantee operator becomes ROLE OPERATOR.
EXECUTE IMMEDIATE
$$
DECLARE
  v_count INTEGER DEFAULT 0;
  v_arguments VARCHAR;
  v_statement VARCHAR;
  e_procedure_not_unique EXCEPTION (-20001, 'Expected exactly one procedure SALES.ADD_PAYMENT; deploy it first. No privilege was changed.');
BEGIN
  -- Converted: Catalog lookup of the converted procedure with SHOW USER PROCEDURES and RESULT_SCAN.
  -- Reason: The "arguments" column has the form ADD_PAYMENT(NUMBER, ...) RETURN <type>; the RETURN part is removed, and so are the square brackets Snowflake shows around optional arguments. The exact "name" filter is needed because _ is a single-character wildcard in LIKE.
  SHOW USER PROCEDURES LIKE 'ADD_PAYMENT' IN SCHEMA SALES;
  SELECT COUNT(*),
         MAX(REPLACE(REPLACE(TRIM(SPLIT_PART("arguments", ' RETURN ', 1)), '[', ''), ']', ''))
    INTO :v_count, :v_arguments
    FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
   WHERE "name" = 'ADD_PAYMENT';
  IF (v_count <> 1) THEN
    RAISE e_procedure_not_unique;
  END IF;
  -- Converted: The single source privilege EXECUTE PROCEDURE for operator -> USAGE on SALES.ADD_PAYMENT for ROLE OPERATOR, with no other privilege, grantee or WITH GRANT OPTION added.
  -- Reason: Object names cannot be passed as USING bind values, so the catalog-derived argument list (not user input) is concatenated into the statement text.
  v_statement := 'GRANT USAGE ON PROCEDURE SALES.' || v_arguments || ' TO ROLE OPERATOR';
  EXECUTE IMMEDIATE :v_statement;
  RETURN v_statement;
END;
$$;
